package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string           // PIC X len=1 = "N"
var WsTotal decimal.Decimal    // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal    // PIC 9(10)V99 len=12 = 0
var WsNewCount int64           // PIC 99 len=2 = 0
var WsShipCount int64          // PIC 99 len=2 = 0
var WsCancelCount int64        // PIC 99 len=2 = 0
var WsInvalid int64            // PIC 99 len=2 = 0
var WsBadQty int64             // PIC 99 len=2 = 0
var WsQtyEd string             // PIC ZZ9 len=3
var WsPriceEd string           // PIC Z,ZZ9.99 len=8
var WsTotalEd string           // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string           // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var OrderRecVar OrderRec

var orderFile *os.File
var orderScanner *bufio.Scanner
var inputDone bool

func main() {
	WsEofFlag = "N"
	WsTotal = decimal.New(0, 0)
	WsGrand = decimal.New(0, 0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0

	MAIN_PARA()
}

func MAIN_PARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		if os.IsNotExist(err) {
			inputDone = true
			SUMMARY_PARA()
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	orderFile = f
	defer f.Close()
	orderScanner = bufio.NewScanner(f)
	// allow long lines
	orderScanner.Split(bufio.ScanLines)

	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE
	SUMMARY_PARA()
}

func READ_PARA() {
	if orderScanner.Scan() {
		line := orderScanner.Text()
		// pad with spaces on right to 15
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		}
		if len(line) > 15 {
			line = line[:15]
		}
		OrderRecVar.OrId = line[0:5]
		OrderRecVar.OrStat = line[5:6]
		OrderRecVar.OrQty = parseIntField(line[6:9])
		OrderRecVar.OrPrice = parseDecimalField(line[9:15], 2)
		WsEofFlag = "N"
		inputDone = false
	} else {
		WsEofFlag = "Y"
		inputDone = true
	}
}

func PROCESS_PARA() {
	WsTotal = decimal.New(0, 0)
	// EVALUATE TRUE
	if OrderRecVar.OrQty == 0 {
		WsBadQty = inc99(WsBadQty, 1)
		// DISPLAY OR-ID " BAD QTY"
		fmt.Fprintln(os.Stdout, OrderRecVar.OrId+" BAD QTY")
	} else if OrderRecVar.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		prod := decimal.NewFromInt(OrderRecVar.OrQty).Mul(OrderRecVar.OrPrice)
		WsTotal = storeDecimal(prod, 2, 10)
		WsNewCount = inc99(WsNewCount, 1)
		SHOW_PARA()
	} else if OrderRecVar.OrStat == "S" {
		// COMPUTE WS-TOTAL ROUNDED = OR-QTY * OR-PRICE * 1.05
		prod := decimal.NewFromInt(OrderRecVar.OrQty).Mul(OrderRecVar.OrPrice).Mul(decimal.New(105, -2))
		// rounded to scale 2
		prod = prod.Round(2)
		WsTotal = storeDecimal(prod, 2, 10)
		WsShipCount = inc99(WsShipCount, 1)
		SHOW_PARA()
	} else if OrderRecVar.OrStat == "C" {
		WsCancelCount = inc99(WsCancelCount, 1)
		SHOW_PARA()
	} else {
		WsInvalid = inc99(WsInvalid, 1)
		fmt.Fprintln(os.Stdout, OrderRecVar.OrId+" BAD STATUS "+OrderRecVar.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	// truncate/overflow for PIC 9(10)V99 : 12 digits total with 2 decimals -> 10 int digits +2 dec =12
	WsGrand = storeDecimal(WsGrand, 2, 12)
	READ_PARA()
}

func SHOW_PARA() {
	WsQtyEd = formatEdited("ZZ9", decimal.NewFromInt(OrderRecVar.OrQty))
	WsPriceEd = formatEdited("Z,ZZ9.99", OrderRecVar.OrPrice)
	WsTotalEd = formatEdited("ZZ,ZZZ,ZZ9.99", WsTotal)
	fmt.Fprintln(os.Stdout, OrderRecVar.OrId+" "+OrderRecVar.OrStat+" "+WsQtyEd+" "+WsPriceEd+" "+WsTotalEd)
}

func SUMMARY_PARA() {
	WsGrandEd = formatEdited("Z,ZZZ,ZZZ,ZZ9.99", WsGrand)
	fmt.Fprintln(os.Stdout, "NEW: "+formatPIC99(WsNewCount)+" SHIPPED: "+formatPIC99(WsShipCount)+" CANCELLED: "+formatPIC99(WsCancelCount))
	fmt.Fprintln(os.Stdout, "INVALID: "+formatPIC99(WsInvalid)+" BAD QTY: "+formatPIC99(WsBadQty))
	fmt.Fprintln(os.Stdout, "GRAND TOTAL: "+WsGrandEd)
}

// helpers

func parseIntField(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return v
}

func parseDecimalField(s string, scale int32) decimal.Decimal {
	// digits only
	var n int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			// space treated as 0? but COBOL would have zeros; treat space as 0
			// Actually numeric field with spaces? treat as 0 digit
			n = n * 10
		}
	}
	return decimal.New(n, -scale)
}

func storeDecimal(v decimal.Decimal, scale int32, totalDigits int) decimal.Decimal {
	// totalDigits includes decimal digits? For PIC 9(8)V99 totalDigits=10 (8+2)
	// Truncate to scale (already done for rounded case), then keep low-order digits
	// Emulate by modulo 10^totalDigits
	// v may be negative not needed
	// Use integer representation: v * 10^scale
	shifted := v.Shift(scale) // v *10^scale
	// truncate toward zero
	shifted = shifted.Truncate(0)
	// modulo
	mod := decimal.New(1, int32(totalDigits)) // 10^totalDigits
	// do positive mod keeping sign
	neg := shifted.Sign() < 0
	if neg {
		shifted = shifted.Abs()
	}
	// shifted mod mod
	// use DivMod via IntPart?
	// compute using decimal: shifted - floor(shifted/mod)*mod
	// Since values fit in int64 range (max 12 digits) we can use int64
	// fallback to decimal division
	if shifted.GreaterThanOrEqual(mod) {
		q := shifted.Div(mod).Truncate(0)
		shifted = shifted.Sub(q.Mul(mod))
	}
	if neg {
		shifted = shifted.Neg()
	}
	return shifted.Shift(-scale)
}

func inc99(v int64, add int64) int64 {
	return (v + add) % 100
}

func formatPIC99(v int64) string {
	v = v % 100
	if v < 0 {
		v += 100
	}
	return fmt.Sprintf("%02d", v)
}

func formatEdited(pic string, val decimal.Decimal) string {
	// determine integer and decimal places
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intPlaces := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intPlaces++
		}
	}
	fracPlaces := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracPlaces++
		}
	}
	neg := val.Sign() < 0
	if neg {
		val = val.Abs()
	}
	// integer part
	intPart := val.Truncate(0).Abs()
	// get integer digits string low-order
	intStr := intPart.StringFixed(0) // no exponent
	// intStr may be like "0"
	// keep low-order intPlaces digits
	digits := make([]byte, intPlaces)
	// fill with '0'
	for i := range digits {
		digits[i] = '0'
	}
	// take last intPlaces chars of intStr
	if len(intStr) <= intPlaces {
		// right align
		copy(digits[intPlaces-len(intStr):], []byte(intStr))
	} else {
		// overflow: keep low-order
		copy(digits, []byte(intStr[len(intStr)-intPlaces:]))
	}
	// fractional digits
	fracDigits := make([]byte, fracPlaces)
	for i := range fracDigits {
		fracDigits[i] = '0'
	}
	if fracPlaces > 0 {
		// get fractional part scaled
		fracVal := val.Sub(val.Truncate(0).Abs())
		// shift
		scaled := fracVal.Shift(int32(fracPlaces)).Truncate(0).Abs()
		s := scaled.StringFixed(0)
		if len(s) <= fracPlaces {
			copy(fracDigits[fracPlaces-len(s):], []byte(s))
		} else {
			copy(fracDigits, []byte(s[len(s)-fracPlaces:]))
		}
	}

	// Now build output
	out := make([]byte, len(pic))
	// find first non-zero in digits
	firstNZ := -1
	for i, d := range digits {
		if d != '0' {
			firstNZ = i
			break
		}
	}
	if firstNZ == -1 {
		firstNZ = intPlaces - 1 // keep last zero
	}

	di := 0
	fi := 0
	for i, c := range pic {
		switch c {
		case 'Z', '9':
			// determine if this is integer or fractional part
			// decide by position relative to dot
			if dotIdx >= 0 && i > dotIdx {
				// fractional
				out[i] = fracDigits[fi]
				fi++
			} else {
				// integer part: check Z suppression
				if c == 'Z' && di < firstNZ {
					out[i] = ' '
				} else {
					out[i] = digits[di]
				}
				di++
			}
		case ',':
			// comma is inside integer part
			// if all more significant integer digits are suppressed, comma becomes space
			// i.e., if di corresponds to suppressed zone
			// di is next digit index to be placed; but comma is between digits
			// If next digit to be placed is within suppressed region? Actually comma suppressed if all digits to its left are suppressed
			// Simpler: if di <= firstNZ and digits up to firstNZ are zeros, then comma is space unless a non-suppressed digit already occurred
			// Use: if di <= firstNZ -> still in leading zero zone => space
			// need to know if we have passed firstNZ
			if di <= firstNZ {
				// need to check if the Z's to left are all suppressed; if di <= firstNZ, comma is in suppressed zone
				// But need to handle case where intPlaces digits all zero: firstNZ = last index, so commas before last digit should be spaces
				out[i] = ' '
			} else {
				out[i] = ','
			}
		case '.':
			out[i] = '.'
		default:
			out[i] = byte(c)
		}
	}
	_ = neg
	return string(out)
}
